{
  "morphology_wrong_forms": [
    {
      "wrong_form": "接戦ります",
      "explanation": "Treats the noun/suru-verb as a godan verb ending in 'ru', which is incorrect."
    },
    {
      "wrong_form": "接戦だ",
      "explanation": "While grammatically possible as ana-adjective style, '接戦する' is the standard verbal form, and treating it as a pure na-adjective without 'na' or 'no' in modifier positions leads to ungrammatical noun-modifying structures."
    },
    {
      "wrong_form": "接戦しった",
      "explanation": "Incorrect past tense inflection for the suru-verb; it should be '接戦した'."
    }
  ],
  "collocation_distractors": [
    {
      "wrong_collocate": "接戦を食べる",
      "explanation": "You cannot 'eat' a close match/contest."
    },
    {
      "wrong_collocate": "接戦を塗装する",
      "explanation": "You cannot 'paint' a competition."
    },
    {
      "wrong_collocate": "接戦をプログラミングする",
      "explanation": "You cannot 'program' a sports match or election battle directly as an object."
    }
  ],
  "collocation_wrong_collocate": {
    "wrong_collocate": "接戦を達成する",
    "explanation": "You achieve goals or results, but you don't 'achieve' (attain) a close contest; you 'fight' or 'win/lose' one."
  },
  "cloze_distractors": [
    {
      "option": "接客",
      "explanation": "Means customer service, completely unrelated to a sports or election battle."
    },
    {
      "option": "接続",
      "explanation": "Means connection or joining, a common kanji mix-up."
    },
    {
      "option": "接触",
      "explanation": "Means contact or touch, semantically incorrect in the context of a competitive match."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "彼は昨日のテストで接戦をとった。",
      "reason": "Tests and exams result in high scores or failing grades, not 'close matches' (接戦)."
    },
    {
      "sentence": "その工場は新しい機械を接戦した。",
      "reason": "Factories install or introduce machinery, not engage in a close contest with it."
    },
    {
      "sentence": "空が暗くなり、接戦が降り始めた。",
      "reason": "Weather phenomena like rain or snow start falling, which does not fit 'close battle'."
    }
  ],
  "spot_incorrect": {
    "sentence": "両チームの実力が拮抗しており、息をのむような接戦を行った。",
    "planted_error": "行った",
    "error_description": "While '行う' can be used with events, for '接戦', the natural verb combinations are '接戦を演じる' or simply using it as an intransitive/suru verb '接戦した'.",
    "corrected_version": "両チームの実力が拮抗しており、息をのむような接戦を演じた。"
  },
