    {
      "fake_form": "接戦性",
      "explanation": "An artificially suffixed noun form meaning 'closeness-of-contest-ness' which does not exist in standard Japanese."
    },
    {
      "fake_form": "接戦らか",
      "explanation": "A fabricated na-adjective inflection blending unrelated morphological endings."
    },
    {
      "fake_form": "お接戦",
      "explanation": "An unnatural polite honorific prefix attached to this specific compound noun."
    }
  ],
  "particle_candidates": [
    "を",
    "に",
    "で",
    "が"
  ]
